// Parse Ollama's response and surface the timing Ollama reports.
// Kept defensive: models sometimes wrap JSON in prose or code fences,
// which is a real observed failure mode (see RESULTS.md).

const out = [];

for (const item of $input.all()) {
  const body = item.json ?? {};
  const raw = String(body.response ?? '');

  let parsed = null;
  let parseError = null;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    // Strip ``` fences, then grab the outermost {...}
    const cleaned = raw.replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '');
    const match = cleaned.match(/\{[\s\S]*\}/);
    if (match) {
      try {
        parsed = JSON.parse(match[0]);
        parseError = 'recovered: model wrapped JSON in extra text';
      } catch (e2) {
        parseError = 'unparseable: ' + e2.message;
      }
    } else {
      parseError = 'no JSON object found in response';
    }
  }

  const ns = Number(body.total_duration ?? 0);
  const evalCount = Number(body.eval_count ?? 0);
  const evalNs = Number(body.eval_duration ?? 0);

  out.push({
    json: {
      ok: parsed !== null,
      parse_error: parseError,
      fields: parsed,
      metrics: {
        model: body.model ?? null,
        total_seconds: ns ? +(ns / 1e9).toFixed(1) : null,
        load_seconds: body.load_duration ? +(body.load_duration / 1e9).toFixed(1) : null,
        eval_tokens: evalCount || null,
        tokens_per_sec: evalNs ? +(evalCount / (evalNs / 1e9)).toFixed(2) : null,
      },
      raw_response: raw,
    },
  });
}

return out;
